"""Meridian CRM permission semantics migrated to Python."""

from __future__ import annotations


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    user_role = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    matching_row = None
    for row in role_rows:
        if (
            row.get("role_id", "") == user_role
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_row = row
            break

    if matching_row is None:
        return False

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    if user_role == "ADMIN":
        return True

    scope = matching_row.get("scope", "")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return record.get("TEAM_CD", "") == user_team
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user_id
    if scope == "NONE":
        return False

    return False
